import { useState } from "react";

const SearchIcon = () => (
  <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
    <circle cx="11" cy="11" r="8" />
    <line x1="21" y1="21" x2="16.65" y2="16.65" />
  </svg>
);

const UserIcon = () => (
  <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round">
    <path d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2" />
    <circle cx="12" cy="7" r="4" />
  </svg>
);

const HeartIcon = () => (
  <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round">
    <path d="M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 0 0 0-7.78z" />
  </svg>
);

const BagIcon = () => (
  <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round">
    <path d="M6 2L3 6v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2V6l-3-4z" />
    <line x1="3" y1="6" x2="21" y2="6" />
    <path d="M16 10a4 4 0 0 1-8 0" />
  </svg>
);

const ZuroLogo = () => (
  <svg width="44" height="44" viewBox="0 0 44 44" fill="none" xmlns="http://www.w3.org/2000/svg">
    <path
      d="M6 34 L6 10 C6 10 10 10 13 16 L22 32 L31 16 C34 10 38 10 38 10 L38 34"
      stroke="url(#zuroGrad)"
      strokeWidth="5"
      strokeLinecap="round"
      strokeLinejoin="round"
      fill="none"
    />
    <defs>
      <linearGradient id="zuroGrad" x1="6" y1="10" x2="38" y2="34" gradientUnits="userSpaceOnUse">
        <stop offset="0%" stopColor="#FF3F6C" />
        <stop offset="100%" stopColor="#FF8C00" />
      </linearGradient>
    </defs>
  </svg>
);

const navItems = [
  { label: "MEN" },
  { label: "WOMEN" },
  { label: "KIDS" },
  { label: "HOME" },
  { label: "BEAUTY" },
  { label: "GENZ" },
  { label: "STUDIO", badge: "NEW" },
];

export default function ZuroHeader() {
  const [activeNav, setActiveNav] = useState(null);
  const [searchFocused, setSearchFocused] = useState(false);
  const [bagCount] = useState(1);

  return (
    <div style={{ fontFamily: "'Helvetica Neue', Arial, sans-serif", background: "#fff", borderBottom: "1px solid #eee", padding: "0 24px" }}>
      <div style={{ maxWidth: 1280, margin: "0 auto", display: "flex", alignItems: "center", height: 72, gap: 32 }}>

        {/* Logo */}
        <div style={{ display: "flex", flexDirection: "column", alignItems: "flex-start", lineHeight: 1, cursor: "pointer", minWidth: 80 }}>
          <ZuroLogo />
          <span style={{ fontSize: 10, color: "#FF3F6C", fontWeight: 700, letterSpacing: 0.5, marginTop: 2 }}>
            The Zuro
          </span>
        </div>

        {/* Nav */}
        <nav style={{ display: "flex", alignItems: "center", gap: 4 }}>
          {navItems.map((item) => (
            <div
              key={item.label}
              onClick={() => setActiveNav(item.label)}
              style={{
                position: "relative",
                padding: "24px 12px",
                cursor: "pointer",
                display: "flex",
                flexDirection: "column",
                alignItems: "center",
                gap: 2,
              }}
            >
              <span
                style={{
                  fontSize: 13,
                  fontWeight: 700,
                  letterSpacing: 0.5,
                  color: activeNav === item.label ? "#FF3F6C" : "#282c3f",
                  whiteSpace: "nowrap",
                  transition: "color 0.15s",
                }}
              >
                {item.label}
                {item.badge && (
                  <span style={{
                    marginLeft: 4,
                    fontSize: 9,
                    fontWeight: 700,
                    color: "#03a685",
                    verticalAlign: "super",
                    letterSpacing: 0,
                  }}>
                    {item.badge}
                  </span>
                )}
              </span>
              {activeNav === item.label && (
                <div style={{
                  position: "absolute",
                  bottom: 0,
                  left: 12,
                  right: 12,
                  height: 2,
                  background: "#FF3F6C",
                  borderRadius: "2px 2px 0 0",
                }} />
              )}
            </div>
          ))}
        </nav>

        {/* Search */}
        <div style={{ flex: 1, maxWidth: 480 }}>
          <div style={{
            display: "flex",
            alignItems: "center",
            gap: 10,
            background: "#f5f5f6",
            borderRadius: 4,
            padding: "10px 16px",
            border: searchFocused ? "1px solid #d4d5d9" : "1px solid transparent",
            transition: "border-color 0.2s",
          }}>
            <span style={{ color: "#94969f" }}><SearchIcon /></span>
            <input
              type="text"
              placeholder="Search for products, brands and more"
              onFocus={() => setSearchFocused(true)}
              onBlur={() => setSearchFocused(false)}
              style={{
                border: "none",
                background: "transparent",
                outline: "none",
                fontSize: 14,
                color: "#282c3f",
                width: "100%",
                fontFamily: "inherit",
              }}
            />
          </div>
        </div>

        {/* Right icons */}
        <div style={{ display: "flex", alignItems: "center", gap: 28, marginLeft: "auto" }}>
          {/* Profile */}
          <button style={{ background: "none", border: "none", cursor: "pointer", display: "flex", flexDirection: "column", alignItems: "center", gap: 3, padding: 0, color: "#282c3f" }}>
            <UserIcon />
            <span style={{ fontSize: 11, fontWeight: 600, color: "#282c3f", letterSpacing: 0.3 }}>Profile</span>
          </button>

          {/* Wishlist */}
          <button style={{ background: "none", border: "none", cursor: "pointer", display: "flex", flexDirection: "column", alignItems: "center", gap: 3, padding: 0, color: "#282c3f" }}>
            <HeartIcon />
            <span style={{ fontSize: 11, fontWeight: 600, color: "#282c3f", letterSpacing: 0.3 }}>Wishlist</span>
          </button>

          {/* Bag */}
          <button style={{ background: "none", border: "none", cursor: "pointer", display: "flex", flexDirection: "column", alignItems: "center", gap: 3, padding: 0, position: "relative", color: "#282c3f" }}>
            <div style={{ position: "relative" }}>
              <BagIcon />
              {bagCount > 0 && (
                <span style={{
                  position: "absolute",
                  top: -6,
                  right: -8,
                  background: "#FF3F6C",
                  color: "#fff",
                  fontSize: 10,
                  fontWeight: 700,
                  width: 17,
                  height: 17,
                  borderRadius: "50%",
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                }}>
                  {bagCount}
                </span>
              )}
            </div>
            <span style={{ fontSize: 11, fontWeight: 600, color: "#282c3f", letterSpacing: 0.3 }}>Bag</span>
          </button>
        </div>
      </div>
    </div>
  );
}
